'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const positions = [];
let total = 0;

for (let i = 0; i < n; i++) {
  positions.push(total);
  total += input[i + 1];
}

if (total % 2 !== 0) {
  console.log('N');
} else {
  const half = total / 2;
  const trees = new Set(positions);
  let antipodalPairs = 0;

  for (const position of positions) {
    if (trees.has((position + half) % total)) {
      antipodalPairs++;
    }
  }

  console.log(antipodalPairs >= 4 ? 'S' : 'N');
}
